#include "server_io_loop_win32.h"
#include <limits.h>
#include <stdio.h>
#include "pal_time.h"
#define PAPACC_SERVER_TICKET_LIFETIME_NS 30000000000ULL
static PAPACC_BOOL network_valid(const PAPACC_SERVER_NETWORK*n){return n!=NULL&&n->is_active&&n->listener_set.is_active&&n->listener_set.entries!=NULL&&n->listener_set.count>0&&n->listener_set.count<=n->listener_set.capacity;}
static PAPACC_U64 deadline(PAPACC_U64 n,PAPACC_U64 t){PAPACC_U64 m=(PAPACC_U64)~(PAPACC_U64)0;return n>m-t?m:n+t;}
static PAPACC_SERVER_PROTOCOL_SLOT_WIN32*free_slot(PAPACC_SERVER_IO_LOOP_WIN32*l){PAPACC_SIZE i;for(i=0;i<l->processor_capacity;++i)if(!l->processor_slots[i].in_use)return &l->processor_slots[i];return NULL;}
static PAPACC_CONNECTION*slot_connection(PAPACC_SERVER_IO_LOOP_WIN32*l,PAPACC_SERVER_PROTOCOL_SLOT_WIN32*s){return papacc_connection_manager_find(l->connection_manager,s->connection_instance_id);}
static void log_message(PAPACC_SERVER_IO_LOOP_WIN32*l,PAPACC_LOG_LEVEL level,const char*message){if(l->logger!=NULL)papacc_log(l->logger,level,"phase2",message);}
static void log_connection(PAPACC_SERVER_IO_LOOP_WIN32*l,PAPACC_LOG_LEVEL level,const char*event,const PAPACC_CONNECTION*c){char address[40],message[160];if(l->logger==NULL||l->logger->minimum_level==PAPACC_LOG_LEVEL_OFF||c==NULL)return;if(papacc_ip_address_format(&c->remote_endpoint.address,address,sizeof(address))!=PAPACC_RESULT_OK)return;if(c->remote_endpoint.address.family==PAPACC_IP_FAMILY_IPV6)(void)snprintf(message,sizeof(message),"%s connection %llu from [%s]:%u",event,(unsigned long long)c->connection_instance_id,address,(unsigned)c->remote_endpoint.port);else(void)snprintf(message,sizeof(message),"%s connection %llu from %s:%u",event,(unsigned long long)c->connection_instance_id,address,(unsigned)c->remote_endpoint.port);log_message(l,level,message);}
static void log_session(PAPACC_SERVER_IO_LOOP_WIN32*l,PAPACC_LOG_LEVEL level,const char*event,PAPACC_U64 sid){char message[128];if(l->logger==NULL||l->logger->minimum_level==PAPACC_LOG_LEVEL_OFF)return;(void)snprintf(message,sizeof(message),"Session %llu %s",(unsigned long long)sid,event);log_message(l,level,message);}
static void shutdown_slot(PAPACC_SERVER_PROTOCOL_SLOT_WIN32*s){switch(s->kind){case PAPACC_SERVER_PROTOCOL_SLOT_KIND_CLASSIFIER:papacc_connection_classifier_shutdown(&s->classifier);break;case PAPACC_SERVER_PROTOCOL_SLOT_KIND_CONTROL_ESTABLISHMENT:papacc_control_processor_shutdown(&s->control_processor);break;case PAPACC_SERVER_PROTOCOL_SLOT_KIND_POST_CONTROL:papacc_post_control_processor_shutdown(&s->post_control_processor);break;case PAPACC_SERVER_PROTOCOL_SLOT_KIND_DATA_ATTACH:papacc_data_attach_processor_shutdown(&s->data_attach_processor);break;default:break;}*s=(PAPACC_SERVER_PROTOCOL_SLOT_WIN32)PAPACC_SERVER_PROTOCOL_SLOT_WIN32_INITIALIZER;}
static PAPACC_RESULT attach_classifier(PAPACC_SERVER_IO_LOOP_WIN32*l,PAPACC_CONNECTION*c,PAPACC_U64 now){PAPACC_SERVER_PROTOCOL_SLOT_WIN32*s=free_slot(l);PAPACC_RESULT r;if(s==NULL){log_connection(l,PAPACC_LOG_WARNING,"Rejected (slot capacity)",c);(void)papacc_connection_manager_remove(l->connection_manager,c->connection_instance_id);return PAPACC_RESULT_LIMIT_EXCEEDED;}*s=(PAPACC_SERVER_PROTOCOL_SLOT_WIN32)PAPACC_SERVER_PROTOCOL_SLOT_WIN32_INITIALIZER;r=papacc_connection_classifier_init(&s->classifier,l->connection_manager,c->connection_instance_id,s->read_scratch,PAPACC_SERVER_PROTOCOL_READ_BUFFER_SIZE,16,deadline(now,l->establishment_timeout_ns));if(r!=PAPACC_RESULT_OK){(void)papacc_connection_manager_remove(l->connection_manager,c->connection_instance_id);return r;}s->connection_instance_id=c->connection_instance_id;s->kind=PAPACC_SERVER_PROTOCOL_SLOT_KIND_CLASSIFIER;s->in_use=PAPACC_TRUE;log_connection(l,PAPACC_LOG_INFO,"Accepted",c);return PAPACC_RESULT_OK;}
static PAPACC_BOOL peer_failure(PAPACC_RESULT r){return r==PAPACC_RESULT_PROTOCOL_ERROR||r==PAPACC_RESULT_NOT_SUPPORTED||r==PAPACC_RESULT_LIMIT_EXCEEDED||r==PAPACC_RESULT_INTERNAL_ERROR||r==PAPACC_RESULT_INVALID_STATE;}
static PAPACC_RESULT transition_classifier(PAPACC_SERVER_IO_LOOP_WIN32*l,PAPACC_SERVER_PROTOCOL_SLOT_WIN32*s){PAPACC_CONNECTION_CLASSIFICATION k;PAPACC_FRAME_HEADER h;PAPACC_FRAMED_READER reader=PAPACC_FRAMED_READER_INITIALIZER;PAPACC_U64 d;PAPACC_RESULT r=papacc_connection_classifier_take(&s->classifier,&k,&h,&reader,&d);if(r!=PAPACC_RESULT_OK)return r;if(k==PAPACC_CONNECTION_CLASSIFICATION_CONTROL){log_connection(l,PAPACC_LOG_INFO,"CONTROL accepted",slot_connection(l,s));r=papacc_control_processor_init_from_reader(&s->control_processor,l->connection_manager,&l->session_manager,&l->channel_manager,s->connection_instance_id,&h,&reader,d);if(r==PAPACC_RESULT_OK)s->kind=PAPACC_SERVER_PROTOCOL_SLOT_KIND_CONTROL_ESTABLISHMENT;}else{log_connection(l,PAPACC_LOG_INFO,"DATA connection accepted",slot_connection(l,s));r=papacc_data_attach_processor_init_from_reader(&s->data_attach_processor,l->connection_manager,&l->session_manager,&l->channel_manager,&l->association_manager,s->connection_instance_id,&h,&reader,d);if(r==PAPACC_RESULT_OK)s->kind=PAPACC_SERVER_PROTOCOL_SLOT_KIND_DATA_ATTACH;}if(r!=PAPACC_RESULT_OK){papacc_framed_reader_shutdown(&reader);{PAPACC_CONNECTION*c=slot_connection(l,s);if(c!=NULL)papacc_connection_close(c);}}return r;}
static PAPACC_RESULT transition_post(PAPACC_SERVER_IO_LOOP_WIN32*l,PAPACC_SERVER_PROTOCOL_SLOT_WIN32*s){PAPACC_FRAMED_READER reader=PAPACC_FRAMED_READER_INITIALIZER;PAPACC_U64 sid=s->control_processor.session_instance_id,cid=s->control_processor.control_channel_instance_id;PAPACC_RESULT r=papacc_control_processor_handoff_reader(&s->control_processor,&reader);if(r==PAPACC_RESULT_OK)r=papacc_post_control_processor_init_from_reader(&s->post_control_processor,l->connection_manager,&l->session_manager,&l->channel_manager,&l->association_manager,sid,cid,&reader);if(r==PAPACC_RESULT_OK){s->kind=PAPACC_SERVER_PROTOCOL_SLOT_KIND_POST_CONTROL;log_session(l,PAPACC_LOG_INFO,"CONTROL established",sid);}else{papacc_framed_reader_shutdown(&reader);(void)papacc_data_association_manager_invalidate_session(&l->association_manager,sid);(void)papacc_channel_manager_close(&l->channel_manager,cid);}return r;}
static PAPACC_BOOL wants_read(const PAPACC_SERVER_PROTOCOL_SLOT_WIN32*s){switch(s->kind){case PAPACC_SERVER_PROTOCOL_SLOT_KIND_CLASSIFIER:return s->classifier.state==PAPACC_CONNECTION_CLASSIFIER_STATE_WAITING_FIRST_HEADER;case PAPACC_SERVER_PROTOCOL_SLOT_KIND_CONTROL_ESTABLISHMENT:return papacc_control_processor_wants_read(&s->control_processor);case PAPACC_SERVER_PROTOCOL_SLOT_KIND_POST_CONTROL:return papacc_post_control_processor_wants_read(&s->post_control_processor);case PAPACC_SERVER_PROTOCOL_SLOT_KIND_DATA_ATTACH:return papacc_data_attach_processor_wants_read(&s->data_attach_processor);default:return PAPACC_FALSE;}}
static PAPACC_BOOL wants_write(const PAPACC_SERVER_PROTOCOL_SLOT_WIN32*s){switch(s->kind){case PAPACC_SERVER_PROTOCOL_SLOT_KIND_CONTROL_ESTABLISHMENT:return papacc_control_processor_wants_write(&s->control_processor);case PAPACC_SERVER_PROTOCOL_SLOT_KIND_POST_CONTROL:return papacc_post_control_processor_wants_write(&s->post_control_processor);case PAPACC_SERVER_PROTOCOL_SLOT_KIND_DATA_ATTACH:return papacc_data_attach_processor_wants_write(&s->data_attach_processor);default:return PAPACC_FALSE;}}
static PAPACC_SIZE buffered(const PAPACC_SERVER_PROTOCOL_SLOT_WIN32*s){switch(s->kind){case PAPACC_SERVER_PROTOCOL_SLOT_KIND_CLASSIFIER:return s->classifier.reader.buffered_length;case PAPACC_SERVER_PROTOCOL_SLOT_KIND_CONTROL_ESTABLISHMENT:return s->control_processor.reader.buffered_length;case PAPACC_SERVER_PROTOCOL_SLOT_KIND_POST_CONTROL:return s->post_control_processor.reader.buffered_length;case PAPACC_SERVER_PROTOCOL_SLOT_KIND_DATA_ATTACH:return s->data_attach_processor.reader.buffered_length;default:return 0;}}
PAPACC_RESULT papacc_server_io_loop_win32_processor_interest(const PAPACC_SERVER_IO_LOOP_WIN32*l,PAPACC_SIZE i,PAPACC_BOOL*r,PAPACC_BOOL*w){if(l==NULL||r==NULL||w==NULL)return PAPACC_RESULT_INVALID_ARGUMENT;if(!l->initialized||i>=l->processor_capacity||!l->processor_slots[i].in_use)return PAPACC_RESULT_INVALID_STATE;*r=wants_read(&l->processor_slots[i]);*w=wants_write(&l->processor_slots[i]);return PAPACC_RESULT_OK;}
PAPACC_RESULT papacc_server_io_loop_win32_processor_scan_index(const PAPACC_SERVER_IO_LOOP_WIN32*l,PAPACC_SIZE o,PAPACC_SIZE*i){if(l==NULL||i==NULL)return PAPACC_RESULT_INVALID_ARGUMENT;if(!l->initialized||l->processor_capacity==0||o>=l->processor_capacity)return PAPACC_RESULT_INVALID_STATE;*i=(l->next_processor_index+o)%l->processor_capacity;return PAPACC_RESULT_OK;}
void papacc_server_io_loop_win32_set_logger(PAPACC_SERVER_IO_LOOP_WIN32*l,const PAPACC_LOGGER*logger){if(l!=NULL&&l->initialized)l->logger=logger;}
PAPACC_RESULT papacc_server_io_loop_win32_init(PAPACC_SERVER_IO_LOOP_WIN32*l,PAPACC_SERVER_NETWORK*n,PAPACC_SERVER_ACCEPTOR_WIN32*a,PAPACC_SESSION*ss,PAPACC_SIZE sc,PAPACC_CHANNEL*cs,PAPACC_SIZE cc,PAPACC_DATA_ASSOCIATION_ENTRY*as,PAPACC_SIZE ac,PAPACC_SERVER_PROTOCOL_SLOT_WIN32*ps,PAPACC_SIZE pc,PAPACC_U64 timeout){PAPACC_CONNECTION_MANAGER*cm;PAPACC_SIZE i;PAPACC_RESULT r;if(l==NULL||n==NULL||a==NULL||(sc&&ss==NULL)||(cc&&cs==NULL)||(ac&&as==NULL)||(pc&&ps==NULL)||timeout==0)return PAPACC_RESULT_INVALID_ARGUMENT;if(l->initialized)return PAPACC_RESULT_INVALID_STATE;if(!network_valid(n)||!a->initialized||a->server_network!=n)return PAPACC_RESULT_INVALID_STATE;cm=papacc_server_acceptor_win32_connection_manager(a);if(cm==NULL||sc>cm->capacity||cc>cm->capacity||pc>cm->capacity)return PAPACC_RESULT_INVALID_STATE;r=papacc_session_manager_init(&l->session_manager,ss,sc);if(r!=PAPACC_RESULT_OK)return r;r=papacc_channel_manager_init(&l->channel_manager,cs,cc,cm,&l->session_manager);if(r!=PAPACC_RESULT_OK){papacc_session_manager_shutdown(&l->session_manager);return r;}r=papacc_server_data_ticket_generator_init(&l->ticket_generator);if(r==PAPACC_RESULT_OK)r=papacc_data_association_manager_init(&l->association_manager,as,ac,&l->session_manager,&l->channel_manager,papacc_server_data_ticket_generator_generate,&l->ticket_generator,PAPACC_SERVER_TICKET_LIFETIME_NS);if(r!=PAPACC_RESULT_OK){papacc_server_data_ticket_generator_shutdown(&l->ticket_generator);papacc_channel_manager_shutdown(&l->channel_manager);papacc_session_manager_shutdown(&l->session_manager);return r;}for(i=0;i<pc;++i)ps[i]=(PAPACC_SERVER_PROTOCOL_SLOT_WIN32)PAPACC_SERVER_PROTOCOL_SLOT_WIN32_INITIALIZER;l->network=n;l->acceptor=a;l->connection_manager=cm;l->association_storage=as;l->association_capacity=ac;l->processor_slots=ps;l->processor_capacity=pc;l->establishment_timeout_ns=timeout;l->initialized=PAPACC_TRUE;return PAPACC_RESULT_OK;}
static PAPACC_RESULT process_slot(PAPACC_SERVER_IO_LOOP_WIN32*l,PAPACC_SERVER_PROTOCOL_SLOT_WIN32*s,PAPACC_BOOL rd,PAPACC_BOOL wr,PAPACC_U64 now){PAPACC_RESULT r=PAPACC_RESULT_OK;if(s->kind==PAPACC_SERVER_PROTOCOL_SLOT_KIND_CLASSIFIER){PAPACC_CONNECTION_CLASSIFIER_STATUS st=PAPACC_CONNECTION_CLASSIFIER_STATUS_UNSPECIFIED;if(rd)r=papacc_connection_classifier_read_once(&s->classifier,&st);if(r==PAPACC_RESULT_OK&&(st==PAPACC_CONNECTION_CLASSIFIER_STATUS_CLASSIFIED_CONTROL||st==PAPACC_CONNECTION_CLASSIFIER_STATUS_CLASSIFIED_DATA))r=transition_classifier(l,s);}else if(s->kind==PAPACC_SERVER_PROTOCOL_SLOT_KIND_CONTROL_ESTABLISHMENT){PAPACC_CONTROL_PROCESSOR_STEP_STATUS st;if(rd)r=papacc_control_processor_read_once(&s->control_processor,&st);else if(wr)r=papacc_control_processor_write_once(&s->control_processor,&st);if(r==PAPACC_RESULT_OK&&s->control_processor.state==PAPACC_CONTROL_PROCESSOR_STATE_ESTABLISHED)r=transition_post(l,s);}else if(s->kind==PAPACC_SERVER_PROTOCOL_SLOT_KIND_POST_CONTROL){PAPACC_POST_CONTROL_STEP_STATUS st;PAPACC_POST_CONTROL_PROCESSOR_STATE before=s->post_control_processor.state;if(rd)r=papacc_post_control_processor_read_once(&s->post_control_processor,now,&st);else if(wr)r=papacc_post_control_processor_write_once(&s->post_control_processor,&st);if(r==PAPACC_RESULT_OK&&before==PAPACC_POST_CONTROL_PROCESSOR_STATE_READY&&s->post_control_processor.state==PAPACC_POST_CONTROL_PROCESSOR_STATE_WRITING_TICKET)log_session(l,PAPACC_LOG_INFO,"DATA ticket issued",s->post_control_processor.session_instance_id);}else if(s->kind==PAPACC_SERVER_PROTOCOL_SLOT_KIND_DATA_ATTACH){PAPACC_DATA_ATTACH_PROCESSOR_STEP_STATUS st;PAPACC_DATA_ATTACH_PROCESSOR_STATE before=s->data_attach_processor.state;if(rd)r=papacc_data_attach_processor_read_once(&s->data_attach_processor,now,&st);else if(wr)r=papacc_data_attach_processor_write_once(&s->data_attach_processor,&st);if(r==PAPACC_RESULT_OK&&before!=PAPACC_DATA_ATTACH_PROCESSOR_STATE_ESTABLISHED&&s->data_attach_processor.state==PAPACC_DATA_ATTACH_PROCESSOR_STATE_ESTABLISHED)log_session(l,PAPACC_LOG_INFO,"DATA successfully attached",s->data_attach_processor.session_instance_id);}if(r!=PAPACC_RESULT_OK&&peer_failure(r)){if(s->kind==PAPACC_SERVER_PROTOCOL_SLOT_KIND_DATA_ATTACH)log_message(l,PAPACC_LOG_WARNING,"DATA attach rejected: invalid, expired, or already-used ticket, invalid state, or malformed frame");else log_message(l,PAPACC_LOG_WARNING,"Peer protocol rejected: malformed frame, incompatible protocol, invalid state, or capacity");}return r;}
static void reap(PAPACC_SERVER_IO_LOOP_WIN32*l,PAPACC_U64 now){PAPACC_SIZE i,n;for(i=0;i<l->processor_capacity;++i){PAPACC_SERVER_PROTOCOL_SLOT_WIN32*s=&l->processor_slots[i];PAPACC_CONNECTION*c=s->in_use?slot_connection(l,s):NULL;if(s->in_use&&c!=NULL&&c->state==PAPACC_CONNECTION_STATE_CLOSED){if(s->kind==PAPACC_SERVER_PROTOCOL_SLOT_KIND_POST_CONTROL)log_session(l,PAPACC_LOG_INFO,"CONTROL closed",s->post_control_processor.session_instance_id);else if(s->kind==PAPACC_SERVER_PROTOCOL_SLOT_KIND_DATA_ATTACH&&s->data_attach_processor.session_instance_id!=0)log_session(l,PAPACC_LOG_INFO,"DATA closed",s->data_attach_processor.session_instance_id);shutdown_slot(s);}}(void)papacc_data_association_manager_expire(&l->association_manager,now,&n);if(n!=0)log_message(l,PAPACC_LOG_DEBUG,"Expired DATA ticket entries removed");for(i=0;i<l->channel_manager.capacity;++i)if(l->channel_manager.storage[i].state==PAPACC_CHANNEL_STATE_CLOSED)(void)papacc_channel_manager_remove(&l->channel_manager,l->channel_manager.storage[i].channel_instance_id);for(i=0;i<l->session_manager.capacity;++i)if(l->session_manager.storage[i].state==PAPACC_SESSION_STATE_CLOSED){PAPACC_U64 sid=l->session_manager.storage[i].session_instance_id;(void)papacc_data_association_manager_invalidate_session(&l->association_manager,sid);(void)papacc_session_manager_remove(&l->session_manager,sid);log_session(l,PAPACC_LOG_INFO,"cleanup complete",sid);}for(i=0;i<l->connection_manager->capacity;++i)if(l->connection_manager->storage[i].state==PAPACC_CONNECTION_STATE_CLOSED)(void)papacc_connection_manager_remove(l->connection_manager,l->connection_manager->storage[i].connection_instance_id);}
PAPACC_RESULT papacc_server_io_loop_win32_poll_once(PAPACC_SERVER_IO_LOOP_WIN32*l,PAPACC_U32 ms){fd_set rs,ws;struct timeval tv;PAPACC_SIZE rc,wc=0,i,o;PAPACC_BOOL bw=PAPACC_FALSE;PAPACC_U64 now;int ready;PAPACC_RESULT r;if(l==NULL)return PAPACC_RESULT_INVALID_ARGUMENT;if(!l->initialized||!network_valid(l->network))return PAPACC_RESULT_INVALID_STATE;rc=l->network->listener_set.count;for(i=0;i<l->processor_capacity;++i)if(l->processor_slots[i].in_use){if(wants_read(&l->processor_slots[i]))++rc;if(wants_write(&l->processor_slots[i]))++wc;if(buffered(&l->processor_slots[i]))bw=PAPACC_TRUE;}if(rc>(PAPACC_SIZE)FD_SETSIZE||wc>(PAPACC_SIZE)FD_SETSIZE)return PAPACC_RESULT_LIMIT_EXCEEDED;if(papacc_pal_monotonic_time_ns(&now)!=PAPACC_RESULT_OK)return PAPACC_RESULT_INTERNAL_ERROR;FD_ZERO(&rs);FD_ZERO(&ws);for(i=0;i<l->network->listener_set.count;++i)FD_SET(l->network->listener_set.entries[i].socket.native_socket,&rs);for(i=0;i<l->processor_capacity;++i){PAPACC_SERVER_PROTOCOL_SLOT_WIN32*s=&l->processor_slots[i];PAPACC_CONNECTION*c;SOCKET sock;if(!s->in_use||(!wants_read(s)&&!wants_write(s)))continue;c=slot_connection(l,s);if(c==NULL||papacc_tcp_connection_transport_win32_get_native_socket(&c->transport,&sock)!=PAPACC_RESULT_OK)continue;if(wants_read(s))FD_SET(sock,&rs);if(wants_write(s))FD_SET(sock,&ws);}tv.tv_sec=bw?0L:(long)(ms/1000U);tv.tv_usec=bw?0L:(long)((ms%1000U)*1000U);ready=select(0,&rs,&ws,NULL,&tv);if(ready==SOCKET_ERROR)return PAPACC_RESULT_INTERNAL_ERROR;for(o=0;o<l->network->listener_set.count;++o){i=(l->next_listener_index+o)%l->network->listener_set.count;if(FD_ISSET(l->network->listener_set.entries[i].socket.native_socket,&rs)){PAPACC_CONNECTION*c=NULL;l->next_listener_index=(i+1U)%l->network->listener_set.count;r=papacc_server_acceptor_win32_accept_ready(l->acceptor,i,&c);if(r==PAPACC_RESULT_OK&&c!=NULL)r=attach_classifier(l,c,now);if(r!=PAPACC_RESULT_OK&&r!=PAPACC_RESULT_LIMIT_EXCEEDED)return r;break;}}for(o=0;o<l->processor_capacity;++o){PAPACC_SERVER_PROTOCOL_SLOT_WIN32*s;PAPACC_CONNECTION*c;SOCKET sock;PAPACC_BOOL dor,dow;if(papacc_server_io_loop_win32_processor_scan_index(l,o,&i)!=PAPACC_RESULT_OK)break;s=&l->processor_slots[i];if(!s->in_use)continue;c=slot_connection(l,s);if(c==NULL||papacc_tcp_connection_transport_win32_get_native_socket(&c->transport,&sock)!=PAPACC_RESULT_OK)continue;dor=wants_read(s)&&(buffered(s)>0||FD_ISSET(sock,&rs));dow=!dor&&wants_write(s)&&FD_ISSET(sock,&ws);if(!dor&&!dow)continue;r=process_slot(l,s,dor,dow,now);if(r!=PAPACC_RESULT_OK&&!peer_failure(r))return r;}if(l->processor_capacity)l->next_processor_index=(l->next_processor_index+1U)%l->processor_capacity;if(papacc_pal_monotonic_time_ns(&now)!=PAPACC_RESULT_OK)return PAPACC_RESULT_INTERNAL_ERROR;for(i=0;i<l->processor_capacity;++i){PAPACC_SERVER_PROTOCOL_SLOT_WIN32*s=&l->processor_slots[i];if(!s->in_use)continue;if(s->kind==PAPACC_SERVER_PROTOCOL_SLOT_KIND_CLASSIFIER){PAPACC_CONNECTION_CLASSIFIER_STATUS st;(void)papacc_connection_classifier_check_deadline(&s->classifier,now,&st);}else if(s->kind==PAPACC_SERVER_PROTOCOL_SLOT_KIND_CONTROL_ESTABLISHMENT){PAPACC_CONTROL_PROCESSOR_STEP_STATUS st;(void)papacc_control_processor_check_deadline(&s->control_processor,now,&st);}else if(s->kind==PAPACC_SERVER_PROTOCOL_SLOT_KIND_DATA_ATTACH&&s->data_attach_processor.state!=PAPACC_DATA_ATTACH_PROCESSOR_STATE_ESTABLISHED){PAPACC_DATA_ATTACH_PROCESSOR_STEP_STATUS st;(void)papacc_data_attach_processor_check_deadline(&s->data_attach_processor,now,&st);}}reap(l,now);return PAPACC_RESULT_OK;}
void papacc_server_io_loop_win32_shutdown(PAPACC_SERVER_IO_LOOP_WIN32*l){PAPACC_SIZE i;if(l==NULL||!l->initialized)return;for(i=0;i<l->processor_capacity;++i)if(l->processor_slots[i].in_use)shutdown_slot(&l->processor_slots[i]);papacc_data_association_manager_shutdown(&l->association_manager);papacc_server_data_ticket_generator_shutdown(&l->ticket_generator);papacc_channel_manager_shutdown(&l->channel_manager);papacc_session_manager_shutdown(&l->session_manager);*l=(PAPACC_SERVER_IO_LOOP_WIN32)PAPACC_SERVER_IO_LOOP_WIN32_INITIALIZER;}
